import Button from 'react-bootstrap/Button';
import Modal from 'react-bootstrap/Modal';
import AddEntityForm from "./AddEntityForm";
import {generateEntity} from "../api/entities";
import {useState} from "react";

function AddEntityModal({show, onHide}) {
    const [selectedEntity, setSelectedEntity] = useState(null);
    const [editingEntity, setEditingEntity] = useState(null);
    const [preview, setPreview] = useState(null);
    const [pendingTitle, setPendingTitle] = useState("");
    const handleClose = () => onHide();

    const handleAdd = (prompt, entityType) => {
        generateEntity(entityType, prompt)
            .then(result => {
                setPreview({title: prompt, description: result.description});
                setPendingTitle(prompt);
            });
    };


    return (
        <>
            <Modal show={show} onHide={handleClose} animation={false}>
                <Modal.Header closeButton>
                    <Modal.Title>Modal heading</Modal.Title>
                </Modal.Header>
                <Modal.Body><AddEntityForm></AddEntityForm></Modal.Body>
                <Modal.Footer>
                    <Button variant="secondary" onClick={handleClose}>
                        Close
                    </Button>
                    <Button variant="primary" onClick={handleClose}>
                        Save Changes
                    </Button>
                </Modal.Footer>
            </Modal>
        </>
    );
}

export default AddEntityModal;
